INSERT INTO "interview" VALUES (74384,'Je n''ai rien remarqué d''inhabituel ce soir-là. J''ai déjà tout raconté à votre collègue la semaine dernière. Ne comptez pas sur moi pour témoigner au tribunal. Je suis désolé de ne pas pouvoir vous aider davantage.'),
 (13175,'Mon fils est rentré tard ce soir-là et m''a dit qu''il y avait beaucoup de police en bas de la rue. Je n''ai pas cherché à en savoir plus. J''ai déjà tout raconté à votre collègue la semaine dernière.'),
 (97489,'Je rentrais du travail et je n''ai croisé personne sur le trajet. Si ça me revient, je vous appelle.'),
 (64730,'Je ne me souviens pas de la date exacte, désolé.'),
 (57340,'Il faisait déjà nuit, je n''ai pas vu grand-chose depuis mon balcon. J''ai déjà tout raconté à votre collègue la semaine dernière. Ma femme était avec moi, elle vous dira la même chose.'),
 (16672,'Nous avons eu une coupure de courant dans tout le quartier pendant une bonne demi-heure. Les gens sont sortis sur le pas de leur porte, ça discutait d''un trottoir à l''autre, puis la lumière est revenue et chacun est rentré chez soi. Je serais incapable de dire qui était dehors à ce moment-là. Vous n''êtes pas le premier à me poser la question.'),
 (47117,'Je rentrais du travail et je n''ai croisé personne sur le trajet.'),
 (93446,'J''ai témoigné dans une affaire il y a trois ans et ça m''a coûté des mois de tracas. Alors cette fois je vais être très clair : je n''étais pas là, je n''ai rien vu, je ne connais personne dans cette histoire et je n''ai aucune intention de me retrouver à nouveau convoqué tous les quinze jours. Je n''ai pas regardé l''heure, mais il ne faisait pas encore tout à fait nuit.'),
 (20989,'J''étais au restaurant avec des amis toute la soirée. Nous sommes arrivés vers dix-neuf heures et nous ne sommes repartis qu''à la fermeture. Le patron pourra le confirmer, il nous connaît bien : nous y allons presque toutes les semaines depuis des années.'),
 (38818,'Je suis infirmière de nuit, je pars de chez moi vers vingt heures et je reviens au petit matin. Il m''arrive de croiser des gens à des heures improbables, mais je ne les remarque plus, c''est devenu une habitude. Cette nuit-là était une nuit comme les autres, avec le même trajet et les mêmes rues vides. Je suis désolé de ne pas pouvoir vous aider davantage.'),
 (97145,'J''ai témoigné dans une affaire il y a trois ans et ça m''a coûté des mois de tracas. Alors cette fois je vais être très clair : je n''étais pas là, je n''ai rien vu, je ne connais personne dans cette histoire et je n''ai aucune intention de me retrouver à nouveau convoqué tous les quinze jours. Si ça me revient, je vous appelle.'),
 (60534,'Un homme est passé avec un sac de sport sur l''épaule, mais c''était en plein après-midi et il marchait tranquillement. Je ne connais personne qui aurait pu faire une chose pareille. J''espère que vous le retrouverez rapidement.'),
 (40727,'Il faisait déjà nuit, je n''ai pas vu grand-chose depuis mon balcon. Ma femme était avec moi, elle vous dira la même chose. Je suis désolé de ne pas pouvoir vous aider davantage.'),
 (32554,'Tout m''a semblé parfaitement normal. J''ai déjà tout raconté à votre collègue la semaine dernière.'),
 (15412,'On m''a dit que quelqu''un du quartier avait « tout vu », mais quand je lui ai demandé, il m''a répondu qu''il ne se souvenait plus de rien. Ma femme était avec moi, elle vous dira la même chose. Si ça me revient, je vous appelle. Vous devriez interroger les gens de l''immeuble d''en face, ils voient tout.'),
 (96479,'Je sortais de mon cours de fitness quand j''ai vu passer une voiture un peu vite. Je n''ai pas pensé une seconde que ça pouvait avoir un rapport avec quoi que ce soit.'),
 (72754,'J''ai vu une voiture passer, mais je n''ai fait attention ni au modèle ni à la plaque. J''espère que vous le retrouverez rapidement.'),
 (36358,'Je promenais mon chien comme chaque soir et il s''est mis à tirer sur sa laisse en aboyant vers le fond de la rue. Sur le moment j''ai pensé à un chat. Avec le recul je me demande s''il n''avait pas entendu quelque chose, mais je ne vais pas bâtir une accusation sur l''humeur d''un teckel. Vous devriez interroger les gens de l''immeuble d''en face, ils voient tout. Ma femme était avec moi, elle vous dira la même chose.'),
 (48581,'On m''a dit que quelqu''un du quartier avait « tout vu », mais quand je lui ai demandé, il m''a répondu qu''il ne se souvenait plus de rien. Ne comptez pas sur moi pour témoigner au tribunal.'),
 (25018,'On m''a dit que quelqu''un du quartier avait « tout vu », mais quand je lui ai demandé, il m''a répondu qu''il ne se souvenait plus de rien. Je ne connais personne qui aurait pu faire une chose pareille. C''est un quartier tranquille d''habitude, ça nous a tous secoués.'),
